    script,
    contains(r'"$RUNNER_TEMP/bench"/*'),
    reason:
        'the working-dir match must be anchored to the shard\'s own '
        'out-of-workspace bench output — sibling shards\' containers '
        'must never be touched (gh-1600 rework)',
  );
});

